import { useNavigate } from "react-router-dom";
import {
  ArrowLeft,
  BookOpen,
  Search,
} from "lucide-react";
import { useMemo, useState } from "react";
import { LiquidGlass } from "../reactbits/LiquidGlass";
import AnimatedList from "../reactbits/vendor/AnimatedList/AnimatedList";
import FadeContent from "../reactbits/vendor/FadeContent/FadeContent";
import BellToggle from "../reactbits/vendor/BellToggle/BellToggle";
import Counter from "../reactbits/vendor/Counter/Counter";
import FlipCard from "../reactbits/vendor/FlipCard/FlipCard";
import GlassSurface from "../reactbits/vendor/GlassSurface/GlassSurface";
import SpringCheck from "../reactbits/vendor/SpringCheck/SpringCheck";
import { AmbientBackdrop } from "../ambient/AmbientBackdrop";
import { cn } from "../../lib/cn";
import { useInkFlow } from "../../store/inkflow";

export function CorpusPage() {
  const navigate = useNavigate();
  const {
    corpus,
    kwicHits,
    searchKwic,
    toggleFavorite,
    removeCorpus,
  } = useInkFlow();
  const [query, setQuery] = useState("");
  const [masteredIds, setMasteredIds] = useState<Set<string>>(new Set());
  const filtered = useMemo(
    () =>
      corpus.filter((entry) =>
        `${entry.term} ${entry.definitionEn} ${entry.meaningsZh.join(" ")} ${entry.collocations.join(" ")}`
          .toLowerCase()
          .includes(query.toLowerCase()),
      ),
    [corpus, query],
  );

  const activeHits = query.trim() ? kwicHits : [];

  const handleSearch = (value: string) => {
    setQuery(value);
    if (value.trim()) void searchKwic(value.trim());
  };

  return (
    <div className="corpus-page corpus-page--interactive">
      <LiquidGlass
        as="header"
        className="subpage-header subpage-header--glass"
        intensity="strong"
        data-motion="enter"
      >
        <button
          type="button"
          className="icon-button"
          onClick={() => navigate("/shelf")}
          aria-label="Back to room"
        >
          <ArrowLeft size={19} />
        </button>
        <div>
          <span className="eyebrow">02 / Corpus → Context → Note</span>
          <h1>Corpus</h1>
        </div>
      </LiquidGlass>

      <GlassSurface
        width="100%"
        height="68px"
        borderRadius={18}
        backgroundOpacity={0.5}
        saturation={1.35}
        distortionScale={-110}
        className="corpus-search corpus-search--glass"
        data-motion="enter"
      >
        <div className="corpus-search__inner">
          <Search size={18} />
          <input
            type="search"
            value={query}
            onChange={(event) => handleSearch(event.target.value)}
            placeholder="Search your language…"
          />
          <span className="library-search__count">
            <Counter
              value={filtered.length}
              fontSize={18}
              gap={1}
              horizontalPadding={0}
              gradientHeight={0}
              textColor="var(--ink)"
              fontWeight={800}
            />
            saved expressions
          </span>
        </div>
      </GlassSurface>

      {activeHits.length > 0 && (
        <section className="kwic-section kwic-section--interactive">
          <div className="section-heading-row">
            <div>
              <span className="eyebrow">Keyword in Context</span>
              <h2>“{query}” in your saved context</h2>
            </div>
            <span>{activeHits.length} hits</span>
          </div>
          <AnimatedList
            items={activeHits.map(
              (hit) => `${hit.left}  ·  ${hit.keyword}  ·  ${hit.right}`,
            )}
            className="corpus-kwic-list"
            itemClassName="corpus-kwic-item"
            showGradients
            displayScrollbar
          />
        </section>
      )}

      <FadeContent
        className="reactbits-reveal"
        blur
        duration={560}
        delay={60}
        threshold={0.04}
      >
        <section
          className="corpus-grid corpus-grid--interactive"
          data-motion="stagger"
        >
          {filtered.map((entry) => {
            const mastered = masteredIds.has(entry.id);
            return (
              <FlipCard
                key={entry.id}
                front={
                  <div className="corpus-flip-face">
                    <header>
                      <div>
                        <span className="mono-label">Saved expression</span>
                        <h2>{entry.term}</h2>
                        <p>{entry.meaningsZh.join("；")}</p>
                      </div>
                      <span
                        className="corpus-flip-face__bell"
                        onClick={(event) => event.stopPropagation()}
                        onPointerDown={(event) => event.stopPropagation()}
                      >
                        <BellToggle
                          offLabel="收藏"
                          onLabel="已收藏"
                          color="#17181a"
                          background="#efeee9"
                          onColor="#ffffff"
                          onBackground="#6a5dff"
                          size="sm"
                          defaultPressed={entry.favorite}
                          onChange={() => void toggleFavorite(entry.id)}
                        />
                      </span>
                    </header>
                    <p className="corpus-entry-card__definition">
                      {entry.definitionEn}
                    </p>
                    <div className="collocation-chips">
                      {entry.collocations.slice(0, 3).map((collocation) => (
                        <button
                          type="button"
                          key={collocation}
                          onClick={(event) => {
                            event.stopPropagation();
                            handleSearch(collocation.split(" ").at(-1) ?? "");
                          }}
                        >
                          {collocation}
                        </button>
                      ))}
                    </div>
                    <span className="corpus-flip-hint">
                      Tap to reveal source
                    </span>
                  </div>
                }
                back={
                  <div className="corpus-flip-face corpus-flip-face--back">
                    <span className="mono-label">Source context</span>
                    <h2>{entry.term}</h2>
                    <blockquote>{entry.definitionEn}</blockquote>
                    <span className="source-link">
                      <BookOpen size={14} />
                      {entry.sourceLabel}
                    </span>
                    <div
                      className="corpus-mastery"
                      onClick={(event) => event.stopPropagation()}
                      onPointerDown={(event) => event.stopPropagation()}
                    >
                      <SpringCheck
                        label="已掌握这个表达"
                        checked={mastered}
                        onChange={(next: boolean) =>
                          setMasteredIds((current) => {
                            const nextSet = new Set(current);
                            if (next) nextSet.add(entry.id);
                            else nextSet.delete(entry.id);
                            return nextSet;
                          })
                        }
                        color="#ffffff"
                        fillColor="#6a5dff"
                        checkColor="#ffffff"
                        fontSize={15}
                      />
                    </div>
                    <button
                      type="button"
                      className="corpus-delete-button"
                      onClick={(event) => {
                        event.stopPropagation();
                        void removeCorpus(entry.id);
                      }}
                    >
                      Delete entry
                    </button>
                  </div>
                }
                axis="y"
                flipOnClick
                draggable={false}
                tilt
                tiltMax={7}
                glare
                width={318}
                height={338}
                radius={18}
                background="#ffffff"
                color="#17181a"
                shadow
                shadowOpacity={0.18}
                className={cn("corpus-flip-card", mastered && "is-mastered")}
              />
            );
          })}
        </section>
      </FadeContent>

      {filtered.length === 0 && (
        <AmbientBackdrop className="empty-state" variant="clouds" active>
          <Search size={30} />
          <h2>No saved language matches “{query}”.</h2>
          <p>Search a different word, then let Leafia explain it in context.</p>
        </AmbientBackdrop>
      )}
    </div>
  );
}
